import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；expected 為依規格人工推導的字面值。

    def test_confirmed_examples(self):
        # 已確認例子
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_all_days_0_to_4(self):
        # 規格：enabled=True 且 day 0..4 -> weekday；含邊界 4（抓 >=4 誤判）
        for d in (0, 1, 2, 3, 4):
            self.assertEqual(route(d, True), "weekday", d)

    def test_weekend_days_5_and_6(self):
        # 規格：day 5..6 -> weekend；含上界 6（抓 ==5 或 >=6 誤判）
        self.assertEqual(route(5, True), "weekend")
        self.assertEqual(route(6, True), "weekend")

    def test_disabled_returns_paused_for_every_valid_day(self):
        # 規格：合法 day 且 enabled=False -> paused（抓忽略 enabled 的退化）
        for d in range(7):
            self.assertEqual(route(d, False), "paused", d)

    def test_invalid_day_out_of_range_rejected(self):
        # 規格：day 不在 0..6 -> ValueError("invalid-day")；邊界 -1、7
        for d in (-1, 7, 100):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, r"^invalid-day$"):
                    route(d, en)

    def test_invalid_day_string_rejected_before_enabled(self):
        # 規格：先驗 day；字串非整數 -> invalid-day，即使 enabled=False 也不得回 paused
        for en in (True, False):
            with self.assertRaisesRegex(ValueError, r"^invalid-day$"):
                route("1", en)

import unittest
from subject import route


class RouteTest(unittest.TestCase):
    # 判準來源：題目規格與已確認例子 route(0,True)=weekday、route(5,True)=weekend

    def test_confirmed_examples(self):
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_all_days_0_to_4(self):
        # 可抓：weekday/weekend 邊界錯在 4 附近（如 day>=4）
        for d in range(0, 5):
            self.assertEqual(route(d, True), "weekday", d)

    def test_weekend_days_5_and_6(self):
        # 可抓：邊界錯成 day>=6 或 day==5
        for d in (5, 6):
            self.assertEqual(route(d, True), "weekend", d)

    def test_disabled_returns_paused_for_every_valid_day(self):
        # 可抓：略過 enabled 檢查、只在部分日子 paused
        for d in range(0, 7):
            self.assertEqual(route(d, False), "paused", d)

    def test_invalid_day_out_of_range(self):
        # 可抓：範圍邊界寫成 <=-1 漏掉、或 >7 漏掉 7
        for d in (-1, 7, 100):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

    def test_invalid_day_non_int_string(self):
        # 可抓：缺少型別檢查；且驗證 day 先於 enabled（enabled=False 仍要拒絕）
        for d in ("3", "abc", ""):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；route(0,True)=weekday、route(5,True)=weekend 為已確認例子。

    def test_confirmed_examples(self):
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_boundaries(self):
        # day 0..4 -> weekday；抓 >=4 / >=6 之類邊界錯誤
        for day in (0, 1, 2, 3, 4):
            self.assertEqual(route(day, True), "weekday", day)

    def test_weekend_boundaries(self):
        for day in (5, 6):
            self.assertEqual(route(day, True), "weekend", day)

    def test_paused_when_disabled_for_every_valid_day(self):
        # 抓忽略 enabled 的退化
        for day in range(7):
            self.assertEqual(route(day, False), "paused", day)

    def test_out_of_range_rejected(self):
        # -1 與 7 剛好在邊界外；enabled 兩種值都要先驗 day
        for day in (-1, 7, 100):
            for enabled in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(day, enabled)

    def test_non_int_string_rejected(self):
        for day in ("0", "5", "abc"):
            for enabled in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(day, enabled)

import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；route(0,True)=weekday、route(5,True)=weekend 為已確認例子。

    def test_confirmed_weekday_example(self):
        self.assertEqual(route(0, True), "weekday")

    def test_confirmed_weekend_example(self):
        self.assertEqual(route(5, True), "weekend")

    def test_last_weekday_is_weekday(self):
        # 邊界 day=4；抓 >=4 誤判
        self.assertEqual(route(4, True), "weekday")

    def test_second_weekend_day_is_weekend(self):
        # day=6；抓只把 5 當週末的錯誤
        self.assertEqual(route(6, True), "weekend")

    def test_disabled_weekday_is_paused(self):
        self.assertEqual(route(0, False), "paused")

    def test_disabled_weekend_is_paused(self):
        self.assertEqual(route(6, False), "paused")

    def test_negative_day_rejected(self):
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(-1, True)

    def test_day_seven_rejected(self):
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(7, True)

    def test_invalid_day_rejected_even_when_disabled(self):
        # 驗 day 須先於 paused 判斷
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(7, False)

    def test_string_day_rejected(self):
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route("1", True)
